const QUESTIONS = [
  {
    id: 'q1',
    text: 'Which of the following are statically typed languages?',
    helpText: 'A statically typed language checks types at compile time rather than at runtime.',
    options: [
      { value: 'typescript', label: 'TypeScript' },
      { value: 'python',     label: 'Python' },
      { value: 'go',         label: 'Go' },
      { value: 'ruby',       label: 'Ruby' },
    ],
    correct: ['typescript', 'go'],
  },
  {
    id: 'q2',
    text: 'Which languages were designed primarily for systems programming?',
    helpText: null,
    options: [
      { value: 'c',          label: 'C' },
      { value: 'javascript', label: 'JavaScript' },
      { value: 'rust',       label: 'Rust' },
      { value: 'lua',        label: 'Lua' },
    ],
    correct: ['c', 'rust'],
  },
  {
    id: 'q3',
    text: 'Which of the following are pure or primarily functional languages?',
    helpText: null,
    options: [
      { value: 'haskell', label: 'Haskell' },
      { value: 'java',    label: 'Java' },
      { value: 'erlang',  label: 'Erlang' },
      { value: 'elixir',  label: 'Elixir' },
    ],
    correct: ['haskell', 'erlang', 'elixir'],
  },
];

// ── Components (pure functions → HTML strings) ──────────────────────────────────

function CheckboxOption({ questionId, option }) {
  const id = `${questionId}-${option.value}`;
  return `
    <div class="checkbox-option">
      <input type="checkbox" id="${id}" name="${questionId}" value="${option.value}">
      <label for="${id}">${option.label}</label>
    </div>`;
}

function HelpText({ id, text }) {
  // Info icon SVG (decorative — aria-hidden)
  const icon = `<svg class="help-text-icon" aria-hidden="true" focusable="false"
      viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg">
    <circle cx="8" cy="8" r="7" stroke="#818cf8" stroke-width="1.5"/>
    <path d="M8 7v4" stroke="#818cf8" stroke-width="1.5" stroke-linecap="round"/>
    <circle cx="8" cy="5" r="0.75" fill="#818cf8"/>
  </svg>`;
  return `<p class="help-text" id="${id}">${icon}${text}</p>`;
}

function CheckboxGroup({ question, index }) {
  const hasHelp = Boolean(question.helpText);
  const describedBy = [
    hasHelp ? `${question.id}-help` : null,
    `${question.id}-error`,
  ].filter(Boolean).join(' ');

  const helpMarkup = hasHelp
    ? HelpText({ id: `${question.id}-help`, text: question.helpText })
    : '';

  const optionsMarkup = question.options
    .map(option => CheckboxOption({ questionId: question.id, option }))
    .join('');

  return `
    <fieldset aria-describedby="${describedBy}">
      <legend>${index + 1}. ${question.text} <span aria-hidden="true">*</span></legend>
      ${helpMarkup}
      <div class="checkbox-options">${optionsMarkup}</div>
      <p class="error-text" id="${question.id}-error" hidden>
        <svg aria-hidden="true" focusable="false" width="14" height="14" viewBox="0 0 14 14" fill="none">
          <path d="M7 1L13 12H1L7 1Z" stroke="#f87171" stroke-width="1.4" fill="none" stroke-linejoin="round"/>
          <path d="M7 5.5V7.5" stroke="#f87171" stroke-width="1.4" stroke-linecap="round"/>
          <circle cx="7" cy="9.5" r="0.6" fill="#f87171"/>
        </svg>
        Error: Please select at least one answer to continue.
      </p>
    </fieldset>`;
}

function FormField({ question, index }) {
  return `
    <div class="form-field" data-question="${question.id}">
      ${CheckboxGroup({ question, index })}
    </div>`;
}

function QuizForm({ questions }) {
  return `
    <form id="quiz-form" novalidate>
      ${questions.map((q, i) => FormField({ question: q, index: i })).join('')}
      <div class="form-actions">
        <button type="submit" class="btn-submit">Submit Quiz</button>
      </div>
    </form>
    <div
      id="quiz-results"
      class="quiz-results"
      aria-live="polite"
      aria-label="Quiz results"
      tabindex="-1"
      hidden
    ></div>`;
}

function QuizHeader() {
  return `
    <h1 class="quiz-heading"><span>Computer Languages</span> Quiz</h1>
    <p class="quiz-subtitle">
      Three questions — select <strong>all correct answers</strong> for each.
      All questions are required.
    </p>`;
}

// Results sub-components

function ResultItem({ question, index, result, correctAnswers }) {
  const cls   = result === 'correct' ? 'result-correct'
              : result === 'partial'  ? 'result-partial'
              :                         'result-incorrect';
  const icon  = result === 'correct' ? '✓' : result === 'partial' ? '◑' : '✗';
  const label = result === 'correct' ? 'Correct'
              : result === 'partial'  ? 'Partial — you missed some correct answers'
              :                         'Incorrect';
  const plural = correctAnswers.length !== 1 ? 's' : '';
  return `
    <div class="result-item">
      <div class="result-item-question">Q${index + 1}: ${question.text}</div>
      <div class="result-item-status ${cls}">
        <span aria-hidden="true">${icon}</span>${label}
      </div>
      <div class="result-detail">Correct answer${plural}: ${correctAnswers.join(', ')}</div>
    </div>`;
}

function QuizResults({ scores }) {
  const total   = scores.length;
  const correct = scores.filter(s => s.result === 'correct').length;
  const emoji   = correct === total ? '🏆' : correct >= Math.ceil(total / 2) ? '🎉' : '📚';
  const suffix  = correct !== 1 ? 's' : '';

  const items = scores
    .map((s, i) => ResultItem({ question: QUESTIONS[i], index: i, ...s }))
    .join('');

  return `
    <div class="results-score">
      <span class="score-emoji" aria-hidden="true">${emoji}</span>
      <div>
        <div class="score-value" aria-label="${correct} out of ${total}">${correct} / ${total}</div>
        <div class="score-label">You answered ${correct} question${suffix} correctly</div>
      </div>
    </div>
    <div class="results-items">${items}</div>
    <button class="btn-retry" type="button" id="btn-retry">Try Again</button>`;
}

// ── Logic ─────────────────────────────────────────────────────────────────────

function getSelections(questionId) {
  return [...document.querySelectorAll(`input[name="${questionId}"]:checked`)]
    .map(el => el.value);
}

function arraysEqual(a, b) {
  const sa = [...a].sort(), sb = [...b].sort();
  return sa.length === sb.length && sa.every((v, i) => v === sb[i]);
}

function scoreQuestion(selected, correct) {
  if (arraysEqual(selected, correct)) return 'correct';
  const hasCorrect = selected.some(v => correct.includes(v));
  const hasWrong   = selected.some(v => !correct.includes(v));
  if (hasCorrect && !hasWrong) return 'partial';
  return 'incorrect';
}

function validate() {
  let firstInvalid = null;
  let allValid = true;

  QUESTIONS.forEach(q => {
    const fieldEl  = document.querySelector(`.form-field[data-question="${q.id}"]`);
    const errorEl  = document.getElementById(`${q.id}-error`);
    const selected = getSelections(q.id);

    if (selected.length === 0) {
      allValid = false;
      errorEl.hidden = false;
      fieldEl?.classList.add('field-error');
      firstInvalid ??= document.querySelector(`input[name="${q.id}"]`);
    } else {
      errorEl.hidden = true;
      fieldEl?.classList.remove('field-error');
    }
  });

  if (firstInvalid) firstInvalid.focus();
  return allValid;
}

function attachChangeListeners() {
  QUESTIONS.forEach(q => {
    document.querySelectorAll(`input[name="${q.id}"]`).forEach(input => {
      input.addEventListener('change', () => {
        if (document.querySelector(`input[name="${q.id}"]:checked`)) {
          document.getElementById(`${q.id}-error`).hidden = true;
          input.closest('.form-field')?.classList.remove('field-error');
        }
      });
    });
  });
}

function handleSubmit(e) {
  e.preventDefault();
  if (!validate()) return;

  const scores = QUESTIONS.map(q => {
    const selected = getSelections(q.id);
    const result = scoreQuestion(selected, q.correct);
    const correctAnswers = q.correct.map(v => q.options.find(o => o.value === v)?.label ?? v);
    return { result, correctAnswers };
  });

  const resultsEl = document.getElementById('quiz-results');
  resultsEl.innerHTML = QuizResults({ scores });
  resultsEl.hidden = false;
  resultsEl.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  resultsEl.focus();

  document.getElementById('btn-retry')
    .addEventListener('click', () => renderApp(document.getElementById('root')));
}

// ── App component & mount ──────────────────────────────────────────────────────

function App() {
  return `
    <div class="quiz-container">
      ${QuizHeader()}
      ${QuizForm({ questions: QUESTIONS })}
    </div>`;
}

function renderApp(root) {
  root.innerHTML = App();
  document.getElementById('quiz-form').addEventListener('submit', handleSubmit);
  attachChangeListeners();
}

renderApp(document.getElementById('root'));
