  const hasHelp = Boolean(question.helpText);
  const describedBy = [
    hasHelp ? `${question.id}-help` : null,
    `${question.id}-error`,
  ].filter(Boolean).join(' ');

  const helpMarkup = hasHelp
    ? HelpText({ id: `${question.id}-help`, text: question.helpText })
    : '';

